"""Central enums for PR165-D3 reports."""
from __future__ import annotations
from enum import Enum
class AgentId(str, Enum):
    RESEARCH = "Research Agent"; PARAMETER_SELECTOR = "Parameter Selector"; RISK_MANAGER = "Risk Manager"; QUANTUM_OPTIMIZER = "Quantum Optimizer"; COMMANDER = "Commander"; GOVERNANCE = "Governance"; DASHBOARD = "Dashboard"
class SelectionDecision(str, Enum):
    CHAMPION = "SELECTED_CHAMPION_COMBO_NOT_LIVE"; CHALLENGER = "SELECTED_CHALLENGER_COMBO_NOT_LIVE"; WATCH = "SELECTED_WATCH_COMBO_NOT_LIVE"; REPLAY_RETEST = "SELECTED_REPLAY_RETEST_COMBO"; PAPER = "SELECTED_PAPER_CANDIDATE_COMBO"; QUANTUM = "SELECTED_QUANTUM_COMPARATOR_COMBO"; REPAIR = "REPAIR_REQUIRED_BEFORE_SELECTION"; REALITY_GAP = "REALITY_MODEL_GAP_REQUIRED"; CONVERSION = "CONVERSION_FRONTIER_CANDIDATE_NOT_POSITIVE"; POSITIVE_EXPANSION = "POSITIVE_EXPANSION_CANDIDATE_NOT_RETESTED"; DATASET_GAP = "DATASET_OR_FIXTURE_GAP_REQUIRED"; FORMULA_GAP = "FORMULA_OR_PLUGIN_GAP_REQUIRED"; NO_TRADE = "NO_TRADE_SELECTION_DECISION"; OWNER_REVIEW = "FUTURE_OWNER_LIVE_REVIEW_CANDIDATE_NOT_AUTHORIZED"; TERMINAL = "TERMINAL_BY_NATURE_WITH_REASON"
class OrderLane(str, Enum):
    NO_TRADE = "NO_TRADE"; PAPER_ONLY = "PAPER_ONLY"; REPLAY_RETEST_REQUIRED = "REPLAY_RETEST_REQUIRED"; REPAIR_REQUIRED = "REPAIR_REQUIRED"; QUANTUM_COMPARE_REQUIRED = "QUANTUM_COMPARE_REQUIRED"; PAPER_CAMPAIGN_READY = "PAPER_CAMPAIGN_READY"; SHADOW_CANDIDATE_NOT_LIVE = "SHADOW_CANDIDATE_NOT_LIVE"; OWNER_REVIEW = "FUTURE_OWNER_LIVE_REVIEW_CANDIDATE_NOT_AUTHORIZED"
class NoOrphanStatus(str, Enum):
    CONNECTED = "PR165_D3_ROUTE_CONNECTED"; SELECTION = "SELECTION_ROUTE_CONNECTED"; REALITY = "REALITY_MODEL_ROUTE_CONNECTED"; CONVERSION = "CONVERSION_FRONTIER_ROUTE_CONNECTED"; QUANTUM = "QUANTUM_ROUTE_CONNECTED"; AGENT = "AGENT_ROUTE_CONNECTED"; REVIEW = "DASHBOARD_GOVERNANCE_COMMANDER_ROUTE_CONNECTED"; TERMINAL = "TERMINAL_ROUTE_CONNECTED"
class LineageStatus(str, Enum):
    FULL = "FULL_PRIOR_SELECTION_LINEAGE_CONSUMED"; PARTIAL = "PARTIAL_PRIOR_SELECTION_LINEAGE_CONSUMED"; ABSENT = "PRIOR_SELECTION_LINEAGE_ARTIFACT_NOT_PRESENT_WITH_EXACT_PATH"
class LineageConflictStatus(str, Enum):
    NONE = "NO_LINEAGE_CONFLICT"; RESOLVED_SM3 = "RESOLVED_BY_NEWER_PR166_SM3_SCORE_MEMORY_AUTHORITY"; RESOLVED_REPAIR = "RESOLVED_BY_REPAIR_OR_REALITY_GAP_ROUTE"; REVIEW = "ROUTED_TO_GOVERNANCE_REVIEW"
ALLOWED_SELECTION_DECISIONS = frozenset(item.value for item in SelectionDecision)
ALLOWED_ORDER_LANES = frozenset(item.value for item in OrderLane)
ALLOWED_NO_ORPHAN_STATUSES = frozenset(item.value for item in NoOrphanStatus)
ALLOWED_LINEAGE_STATUSES = frozenset(item.value for item in LineageStatus)
ALLOWED_LINEAGE_CONFLICT_STATUSES = frozenset(item.value for item in LineageConflictStatus)
